 public void Viewport(Rect r){cameraView.rect=r;Focus(mode);}
 public void Focus(string value){mode=value;pitch=mode=="side"?24:70;yaw=0;orbitTarget=new Vector3(0,0,.35f);distance=Mathf.Max(11.8f,8.0f/Mathf.Max(.4f,cameraView.aspect));if(value=="detail"){orbitTarget=Center(active);distance=1.65f;}if(value=="hand"){orbitTarget=new Vector3(active<5?-1.72f:1.72f,.15f,.25f);distance=6.2f;}if(value=="studio")distance*=1.18f;PositionCamera();}
