 public void Mask(int i,Vector2 uv,float radius=.13f){var t=masks[i];int cx=Mathf.RoundToInt(uv.x*(t.width-1)),cy=Mathf.RoundToInt(uv.y*(t.height-1)),rx=Mathf.CeilToInt(radius*t.width),ry=Mathf.CeilToInt(radius*t.height);for(int y=Mathf.Max(0,cy-ry);y<=Mathf.Min(t.height-1,cy+ry);y++)for(int x=Mathf.Max(0,cx-rx);x<=Mathf.Min(t.width-1,cx+rx);x++)if(Mathf.Pow((x-cx)/(float)rx,2)+Mathf.Pow((y-cy)/(float)ry,2)<=1)t.SetPixel(x,y,Color.white);t.Apply(false);}
 public void Apply(int i,Nail n,float reveal=1,float old=0,float dirt=0,float dust=0){
