 public void Studio(SaveData data){matRenderer.material.color=Rules.ColorOf(data.studio.mat=="sage-mat"?"#b9c8ba":"#edd4d2");trayRenderer.material.color=Rules.ColorOf(data.studio.tray=="rose-tray"?"#b7757e":"#fff1dd");float sign=data.studio.layout=="left"?-1:1;tray.position=new Vector3(sign<0?-2*tray.GetComponent<MeshFilter>().sharedMesh.bounds.center.x:0,0,0);display.position=new Vector3(sign<0?-2*display.GetComponent<MeshFilter>().sharedMesh.bounds.center.x:0,0,sign<0?.4f:0);board.transform.position=display.position;bool own=Rules.Own(data,"display");display.gameObject.SetActive(own);board.SetActive(own);var work=data.album.FirstOrDefault(w=>w.id==data.studio.display);if(own){var tex=new Texture2D(512,384);var pixels=Enumerable.Repeat(Rules.ColorOf("#f7efe4"),512*384).ToArray();tex.SetPixels(pixels);if(work!=null)for(int i=0;i<10;i++){var mini=new Texture2D(64,128);RenderTexture2D(work.design.nails[i],mini,true);for(int y=0;y<128;y++)for(int x=0;x<64;x++){var c=mini.GetPixel(x,y);if(c.a>.1f)tex.SetPixel(25+i%5*100+x,30+(1-i/5)*170+y,c);}Destroy(mini);}tex.Apply();var rend=board.GetComponent<Renderer>();var oldTex=rend.material.mainTexture;rend.material.mainTexture=tex;if(oldTex)Destroy(oldTex);}}
 public static void RenderTexture2D(Nail n,Texture2D tex,bool clip){
  var p=n.polish??new Polish();var col=Rules.ColorOf(n.@base);var under=Rules.ColorOf("#e8b8ad");var blank=Rules.ColorOf("#e8b8ad");var tip=Rules.ColorOf(p.tipColor);var aura=Rules.ColorOf(p.auraColor);var cat=Rules.ColorOf(p.catColor);var grad=Rules.ColorOf(n.gradient?.color);float alpha=1-Mathf.Pow(1-p.opacity,p.layers);int w=tex.width,h=tex.height;var pixels=new Color[w*h];
  for(int y=0;y<h;y++)for(int x=0;x<w;x++){float u=x/(float)(w-1),v=y/(float)(h-1);var c=col;if(Rules.Gradient(n)){float a=n.gradient.angle*Mathf.Deg2Rad,t=(u-.5f)*Mathf.Sin(a)+(v-.5f)*Mathf.Cos(a);c=Color.Lerp(col,grad,Mathf.InverseLerp(-n.gradient.range/2,n.gradient.range/2,t));}if(clip)c=Color.Lerp(under,c,alpha);if(n.unpainted)c=blank;if(n.pattern=="french"&&v>1-p.tipWidth*(.3f+.7f*Mathf.Abs(2*u-1))){c=tip;}if(n.pattern=="aura"){float t=Mathf.Exp(-Vector2.SqrMagnitude(new Vector2((u-.5f)*1.1f,v-.53f))/(p.auraSize*p.auraSize*.1f));c=Color.Lerp(c,aura,t*.9f);}if(n.pattern=="marble"){float v1=Mathf.Sin(v*25+Mathf.Sin(u*10)*2);if(v1>.94f)c=Color.Lerp(c,Color.white,.6f);}if(p.dots&&Mathf.Repeat(u*4+((int)(v*7)%2)*.4f,1)>.43f&&Mathf.Repeat(u*4+((int)(v*7)%2)*.4f,1)<.57f&&Mathf.Repeat(v*7,1)>.42f&&Mathf.Repeat(v*7,1)<.58f)c=tip;if(clip&&n.finish=="catEye"){float band=(u-n.magnet.u)*Mathf.Cos(n.magnet.angle)+(v-.5f)*Mathf.Sin(n.magnet.angle);c=Color.Lerp(c,cat,Mathf.Exp(-Mathf.Pow(band/Mathf.Max(.03f,p.catWidth),2))*.6f);}if(clip&&p.chrome>.1f)c=Color.Lerp(c,Color.white,Mathf.Exp(-Mathf.Pow((u-.47f)/.08f,2))*.6f*p.chrome);if(n.finish=="glitter"&&Mathf.PerlinNoise(x*7.9f,y*9.1f)>.78f)c=Color.Lerp(c,Color.white,.7f);bool opaqueTip=n.pattern=="french"&&v>1-p.tipWidth*(.3f+.7f*Mathf.Abs(2*u-1));c.a=clip||n.unpainted||opaqueTip?1:alpha;if(clip&&(Mathf.Abs(u-.5f)>Rules.Half(n.shape,v)*.94f||v<.02f||v>.98f))c=Color.clear;pixels[y*w+x]=c;}
  // Decals and hand-drawn strokes share UV coordinates with the Blender nail grids.
  foreach(var d in n.decorations){if(d.hidden||(!clip&&new[]{"gem","pearl","droplet"}.Contains(d.type)))continue;float radius=.085f*d.scale;int cx=(int)(d.u*w),cy=(int)(d.v*h),rx=(int)(radius*w),ry=(int)(radius*h*.55f);for(int y=Mathf.Max(0,cy-ry);y<Mathf.Min(h,cy+ry+1);y++)for(int x=Mathf.Max(0,cx-rx);x<Mathf.Min(w,cx+rx+1);x++){float dx=(x-cx)/(float)Mathf.Max(1,rx),dy=(y-cy)/(float)Mathf.Max(1,ry),a=Mathf.Atan2(dy,dx)-d.rotation,r=Mathf.Sqrt(dx*dx+dy*dy);bool draw=r<1;switch(d.type){case "star":draw=r<.62f+.3f*Mathf.Cos(a*5);break;case "flower":draw=r<.7f+.24f*Mathf.Cos(a*5);break;case "heart":draw=Mathf.Pow(dx*dx+dy*dy-1,3)-dx*dx*dy*dy*dy<0;break;case "bow":case "butterfly":draw=Mathf.Abs(dx)>.15f&&r<1-Mathf.Abs(dy)*.3f;break;case "foil":draw=r<.7f+.2f*Mathf.Sin(a*7);break;}if(draw&&pixels[y*w+x].a>.01f)pixels[y*w+x]=Rules.ColorOf(new[]{"star","foil","gem"}.Contains(d.type)?"#d2b36d":"#fff4e5");}}
  var unmarked=n.strokes.Any(s=>s.kind=="erase")?(Color[])pixels.Clone():null;
  foreach(var s in n.strokes){for(int j=0;j<s.points.Count;j++){var a=s.points[j];var b=j==0?a:s.points[j-1];int count=Mathf.Max(1,Mathf.CeilToInt(Vector2.Distance(new Vector2(a.u,a.v),new Vector2(b.u,b.v))*h*2));for(int k=0;k<=count;k++){float t=k/(float)count,u=Mathf.Lerp(a.u,b.u,t),v=Mathf.Lerp(a.v,b.v,t);int cx=(int)(u*w),cy=(int)(v*h),r=Mathf.Max(1,(int)(s.size*w*.5f));for(int y=Mathf.Max(0,cy-r);y<=Mathf.Min(h-1,cy+r);y++)for(int x=Mathf.Max(0,cx-r);x<=Mathf.Min(w-1,cx+r);x++)if((x-cx)*(x-cx)+(y-cy)*(y-cy)<=r*r&&pixels[y*w+x].a>.01f)pixels[y*w+x]=s.kind=="erase"?unmarked[y*w+x]:Rules.ColorOf(s.color);}}}
  tex.SetPixels(pixels);tex.Apply(false);
 }
